def load(p):
    try:
        x=json.loads(p.read_text(encoding='utf-8')); return x if isinstance(x,dict) else {}
    except Exception:return {}

def main():
    p=load(PREFLIGHT); d=p.get('content_director_4') or {}; selected=p.get('selected_opportunity') or {}; feedback=load(FEEDBACK); fmt=str(d.get('recommended_format') or 'TOP MOVERS').upper(); sym=re.sub(r'USDT$','',str(selected.get('symbol') or d.get('primary_story',{}).get('symbol') or '').upper())
    if not re.fullmatch(r'[A-Z0-9]{1,15}',sym):raise SystemExit('Script Director: authoritative selected symbol is missing or invalid')
    lane=str(selected.get('category') or d.get('primary_story',{}).get('lane') or '').lower(); style=STYLE_BY_LANE.get(lane,'analyst')
    learned=(feedback.get('learned_preferences') or {}).get('style') or {}; learned_style=str(learned.get('prefer') or '').strip().lower()
    if learned_style and int(learned.get('sample') or 0)>=3 and learned_style in QUESTIONS:
        style=learned_style
    candidates=[x.replace('${symbol}',f'${sym}') for x in HOOKS.get(fmt,HOOKS['TOP MOVERS'])]
    if fmt=='COIN VS COIN':
        pair=(d.get('primary_story') or {}).get('chart_symbols') or [sym,'BTC']; b=pair[1] if len(pair)>1 else 'BTC'; candidates=[x.replace('${symbol}',f'${sym}').replace('${a}',f'${sym}').replace('${b}',f'${b}') for x in candidates]
    news_title=str(selected.get('news_title') or '').strip(); news_source=str(selected.get('news_source') or '').strip(); questions=QUESTIONS.get(style,QUESTIONS['analyst'])
    seed=hashlib.sha256((sym+fmt+news_title+style).encode()).hexdigest(); qidx=int(seed[:8],16)%len(questions); preferred_hook=(feedback.get('learned_preferences') or {}).get('hook_type') or {}
    directive={'version':'4.4','format':fmt,'primary_symbol':sym,'news_title':news_title,'news_source':news_source,'style':style,'performance_learning':{'preferred_style':learned_style or None,'style_sample':learned.get('sample',0),'preferred_hook_type':preferred_hook.get('prefer')},'hook_candidates':candidates,'question_candidates':questions,'writing_contract':['Write a finished Binance Square post, not an outline. Make the first two lines earn the next scroll.','Use HOOK → VERIFIED EVENT/OBSERVATION → WHY NOW → EVIDENCE → INTERPRETATION → MARKET IMPACT → TRADINGVIEW/LEVELS → BULL/BEAR OR CONFIRMATION → NEXT WATCH → ONE SPECIFIC QUESTION.','The hook must create curiosity without hiding the actual subject. Never use fake urgency or unsupported claims.','For news, put the real event near the top and clearly separate FACT from interpretation. Include source context when useful.','For market moves, do not merely restate the percentage. Explain what makes the move notable: volume, range, structure, catalyst, relative strength or follow-through.','Add one useful insight a reader can act on conceptually: a level, confirmation condition, invalidation, comparison or question to watch.','Write like a sharp human market observer: concrete, conversational, confident but not certain. Vary sentence length and paragraph rhythm.','Avoid filler openings, generic “here is what you need to know” language, repeated emoji patterns and canned CTAs.','Use exact supplied evidence only. Never invent price, volume, source, target, creator call or outcome.','For technical content, keep levels synchronized with verified data and TradingView.','Targets, stops, breakout and 10x/20x ideas are conditional scenarios, never guarantees.','For public creator calls, attribute the original call and distinguish it from our measured outcome. Never imply our system made the call unless it actually did.','Use exactly one question, and make it a concrete decision/observation question rather than “what do you think?”.','Do not imitate another creator. Learn only from aggregate performance patterns.'],'retention_rules':['First line: specific tension or curiosity.','Second line: immediate context or payoff.','Every paragraph should add new information.','Prefer one memorable number or level over a pile of numbers.','Use short mobile-first paragraphs.','No wall of text.','No repetitive “fresh check / quick market check” framing.','No guaranteed-pump language.'],'style_rotation':['newsroom','analyst','conversational','contrarian','high_energy','data_driven','discovery','macro_analyst','accountability','debate','teacher'],'recommended_question_index':qidx}
    OUT.parent.mkdir(parents=True,exist_ok=True);OUT.write_text(json.dumps(directive,indent=2,ensure_ascii=False),encoding='utf-8');p['script_director_4']=directive;p['content_director_instruction']=f'Use authoritative asset ${sym}, format {fmt}, style {style}, and TradingView visual package {((d.get("primary_story") or {}).get("chart_symbols") or [sym])}.';PREFLIGHT.write_text(json.dumps(p,indent=2,ensure_ascii=False),encoding='utf-8');print(json.dumps({'status':'OK','version':'4.4','format':fmt,'symbol':sym,'style':style,'performance_style_learning':bool(learned_style and int(learned.get('sample') or 0)>=3)},indent=2))
